/**
 * This module provides utility functions for resolving data series support on layers,
 * including looking up a data series by name.
 *
 * @since 5.1
 */
import type DataSeriesInfo from "./TimeSeriesInfo.js";
import type { FeatureLikeLayerOrAdapter } from "../../smartMapping/support/adapters/types.js";

/**
 * Returns the data series definition from a layer based on its name.
 *
 * @param layer - The layer or adapter to inspect.
 * @param dataSeriesName - The name of the data series to resolve.
 * @returns The matching data series definition, if found.
 * @since 5.1
 */
export function getDataSeriesInfo(layer: FeatureLikeLayerOrAdapter, dataSeriesName: string | undefined): DataSeriesInfo | undefined;